pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    Token token;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
        token = new Token();
    }

    function testFuzz_property(address caller, address to, uint256 amount) public {
        vm.assume(caller != address(this));
        token.reset();
        vm.prank(caller);
        try c.transferAnyERC20Token(address(token), to, amount) returns (bool) {
        } catch {
        }
        assertTrue(!token.wasCalled());
    }
}

contract Token {
    bool public called;

    function reset() external {
        called = false;
    }

    function wasCalled() external view returns (bool) {
        return called;
    }

    function transfer(address, uint256) external returns (bool) {
        called = true;
        return true;
    }
}
